NL = '\n'
lines = [
    'package com.abemu.coaster.sim', '',
    '// GENERATED by an OSM extraction script from OpenStreetMap roller_coaster=track / roller_coaster=station data.',
    '// Map data (c) OpenStreetMap contributors, available under the ODbL (https://www.openstreetmap.org/copyright).', '',
    '/** Real top-down layouts. Each starts at the station entry and follows the direction of travel. */',
    'object RealLayouts {',
    '    /**',
    '     * @param stationEnd fraction of the circuit where the station building ends.',
    '     * @param liftStart fraction where the lift / launch straight begins.',
    '     * @param liftEnd fraction where that straight ends (the crest if [liftTagged]; otherwise it may include the first drop).',
    '     * @param points (fraction of circuit, x, y) in a 100 x 56 plan box.',
    '     */',
    '    class Layout(',
    '        val osmLengthM: Double,',
    '        val stationEnd: Double,',
    '        val liftStart: Double,',
    '        val liftEnd: Double,',
    '        val liftTagged: Boolean,',
    '        val points: List<Triple<Double, Double, Double>>,',
    '        /** Fraction where the switch track meets the launch line (rides with a rear spike), else -1. */',
    '        val switchAt: Double = -1.0,',
    '        /** Spike line from the switch back to the spike tower, (x, y) in the plan box. */',
    '        val spike: List<Pair<Double, Double>> = emptyList(),',
    '    )', '',
    '    val byId: Map<String, Layout> = mapOf(',
]
for rid, name, total, se, ls, le, tg, pl, sw, sp in out:
    lines.append(f'        "{rid}" to Layout({round(total, 1)}, {round(se, 5)}, {round(ls, 5)}, {round(le, 5)}, {str(tg).lower()}, listOf( // {name}')
    row = [f'Triple({u}, {x}, {y})' for u, x, y in pl]
    for k in range(0, len(row), 4):
        lines.append('            ' + ', '.join(row[k:k + 4]) + ',')
    if sp:
        lines.append(f'        ), switchAt = {sw}, spike = listOf(')
        row = [f'{x} to {y}' for x, y in sp]
        for k in range(0, len(row), 6):
            lines.append('            ' + ', '.join(row[k:k + 6]) + ',')
        lines.append('        )),')
    else:
        lines.append('        )),')
lines += ['    )', '}', '']
open(outkt, 'w', encoding='utf-8').write(NL.join(lines))

write_scenery(scenery)
